DELETE FROM `quest_template_locale` WHERE `ID` = 820 AND `locale` = 'zhTW';
INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES (820,'zhTW','暫無內容','你體內的確存在著力量的精神——或者那僅僅只是運氣？$B$B現在的年輕人總是依靠運氣，或是指望那些比自己更為強大的人對他們施以慷慨。很少有人願意走自己的路。總是向別人乞求幫助……不願完成任何任務就想獲得報酬。我肯定你就是這樣。$B$B不過我對你還有點希望。我還需要一樣東西，$N：8束微光草，在剃刀嶺西北部的雷霆山上可以找到。','找8束微光草，交給森金村的沃納爾大師。','','','','','','',0);

DELETE FROM `npc_text_locale` WHERE `ID` = 20551 AND `Locale` = 'zhTW';
INSERT INTO `npc_text_locale` (`ID`, `Locale`, `Text0_0`, `Text0_1`, `Text1_0`, `Text1_1`, `Text2_0`, `Text2_1`, `Text3_0`, `Text3_1`, `Text4_0`, `Text4_1`, `Text5_0`, `Text5_1`, `Text6_0`, `Text6_1`, `Text7_0`, `Text7_1`) VALUES (20551, 'zhTW', '你好! $N', '你好! $N', '我們位於標記地點，指揮官。亞希克斯已經與我走散了。請求支援。', '阿瑞克斯！請求支援！我被困在礦洞，我...我不確定我到底在什麼位置，但是我很清楚在地面上我已經把追捕者甩開了。', '我無法跟隨標記出來，這路上有太多食肉動物了。派些人手……順著標記進來……亞希克斯，通話結束。', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
